import itertools
import sys

def solve_pbe_string_transform(examples):
    """
    Given a list of (input_str, output_str) pairs, find a sequence of replace operations
    (each of the form replace('A', 'B')) that transforms every input to its corresponding output.

    Returns a list of strings representing the replace calls, e.g., ["replace('a', 'b')", ...].
    """

    def apply_program(s, program):
        """Apply a replace('A', 'B') program to string s."""
        a, b = program
        return s.replace(a, b)

    def check_programs(programs):
        """Check if a sequence of programs transforms all examples correctly."""
        for inp, out in examples:
            s = inp
            for a, b in programs:
                s = apply_program(s, (a, b))
            if s != out:
                return False
        return True

    def generate_candidates():
        """Generate all possible replace('A', 'B') candidates."""
        candidates = []
        # A can be 1, 2, or 3 characters
        # B can be 0, 1, 2, or 3 characters
        # We need to consider all printable ASCII characters that might appear
        # For efficiency, let's collect all unique characters from inputs and outputs
        chars = set()
        for inp, out in examples:
            chars.update(inp)
            chars.update(out)
        # Also include some common characters that might be needed for insertion
        extra_chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
        chars.update(extra_chars)

        char_list = sorted(chars)

        for len_a in range(1, 4):
            for len_b in range(0, 4):
                # Generate all possible A strings of length len_a
                if len_a == 1:
                    a_strings = char_list
                else:
                    a_strings = [''.join(p) for p in itertools.product(char_list, repeat=len_a)]

                # Generate all possible B strings of length len_b
                if len_b == 0:
                    b_strings = ['']
                elif len_b == 1:
                    b_strings = char_list
                else:
                    b_strings = [''.join(p) for p in itertools.product(char_list, repeat=len_b)]

                for a in a_strings:
                    for b in b_strings:
                        candidates.append((a, b))

        return candidates

    candidates = generate_candidates()

    # Try sequences of length 1 to 5
    for length in range(1, 6):
        for combo in itertools.product(candidates, repeat=length):
            if check_programs(combo):
                return [f"replace('{a}', '{b}')" for a, b in combo]

    return []

