import itertools

def solve_string_transform_pbe(examples):
    """
    Given a list of (input_str, output_str) pairs, find a sequence of replace(a, b)
    operations (applied left-to-right) that transforms each input to its corresponding output.

    Constraints:
      - 1 <= len(a) <= 3
      - 0 <= len(b) <= 3
      - At most 5 operations
    """

    def apply_replace(s, a, b):
        """Apply str.replace semantics: replace first occurrence of a with b."""
        return s.replace(a, b, 1)

    def check_program(programs, in_str, out_str):
        """Check if a sequence of programs transforms in_str to out_str."""
        s = in_str
        for a, b in programs:
            s = apply_replace(s, a, b)
        return s == out_str

    def get_candidates():
        """Generate all possible (a, b) pairs with 1 <= len(a) <= 3 and 0 <= len(b) <= 3."""
        # Collect all unique substrings of length 1-3 from all inputs and outputs
        all_chars = set()
        all_substrings = set()
        for in_str, out_str in examples:
            for s in [in_str, out_str]:
                for i in range(len(s)):
                    for j in range(i+1, min(i+4, len(s)+1)):
                        all_substrings.add(s[i:j])
                    all_chars.add(s[i])

        # Also add single characters
        candidates = set()
        for a in all_substrings:
            if 1 <= len(a) <= 3:
                # b can be empty or any single char, or any substring of length 1-3
                candidates.add((a, ''))
                for c in all_chars:
                    candidates.add((a, c))
                for b in all_substrings:
                    if 0 < len(b) <= 3:
                        candidates.add((a, b))
        return list(candidates)

    # Try sequences of length 1 to 5
    candidates = get_candidates()

    for length in range(1, 6):
        for combo in itertools.product(candidates, repeat=length):
            # Check if this sequence works for ALL examples
            valid = True
            for in_str, out_str in examples:
                if not check_program(combo, in_str, out_str):
                    valid = False
                    break
            if valid:
                # Convert to string format
                return [f"replace('{a}', '{b}')" for a, b in combo]

    return []
